import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { captureFromHook } from "../chatSessions/index.js";
import { runCaptureHook } from "./captureHook.js";
vi.mock("../chatSessions/index.js", () => ({
    captureFromHook: vi.fn(),
}));
const SESSION = "capture-hook-session";
const REPLAY_LAUNCH = {
    session_id: SESSION,
    transcript_path: "/tmp/transcript.jsonl",
    tool_input: { command: "bitfab-replay --metadata bitfab-wait=batch-1" },
};
describe("runCaptureHook", () => {
    let home;
    function launchesFile() {
        return path.join(home, ".config", "bitfab", "sessions", `${SESSION}.replay-launches.jsonl`);
    }
    beforeEach(() => {
        home = fs.mkdtempSync(path.join(os.tmpdir(), "bitfab-capture-hook-"));
        vi.stubEnv("HOME", home);
        vi.mocked(captureFromHook).mockReturnValue(new Promise(() => undefined));
    });
    afterEach(() => {
        vi.unstubAllEnvs();
        fs.rmSync(home, { recursive: true, force: true });
    });
    it("records a replay launch before session capture finishes", async () => {
        void runCaptureHook("PreToolUse", "claude-code", REPLAY_LAUNCH);
        await new Promise((resolve) => setTimeout(resolve, 0));
        expect(fs.readFileSync(launchesFile(), "utf-8")).toContain('"batch-1"');
    });
    it("does not record launches for a host with no end-of-turn hook", async () => {
        void runCaptureHook("PreToolUse", "amp", REPLAY_LAUNCH);
        await new Promise((resolve) => setTimeout(resolve, 0));
        expect(fs.existsSync(launchesFile())).toBe(false);
    });
});
